pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzedSender) public {
        vm.assume(fuzzedSender != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        vm.assume(fuzzedSender != address(0));
        vm.prank(fuzzedSender);
        bool ok;
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

